# 采样策略配置（存储在 ConfigMap）
apiVersion: v1
kind: ConfigMap
metadata:
  name: jaeger-sampling-strategies
  namespace: observability
data:
  strategies.json: |
    {
      "default_strategy": {
        "type": "probabilistic",
        "param": 0.01
      },
      "service_strategies": [
        {
          "service": "payment-service",
          "type": "adaptive",
          "param": 0.5,
          "operation_strategies": [
            {
              "operation": "processPayment",
              "type": "probabilistic",
              "param": 1.0
            }
          ]
        },
        {
          "service": "api-gateway",
          "type": "rateLimiting",
          "param": 100
        }
      ],
      "operation_strategies": [
        {
          "operation": "/health",
          "type": "probabilistic",
          "param": 0.0
        },
        {
          "operation": "/metrics",
          "type": "probabilistic",
          "param": 0.0
        }
      ]
    }
